//! Embedded Attune Application Window Icon (Base64 Encoded PNG).
//! Prevents fallback to generic Wayland or blank placeholder icons.

use base64::prelude::*;
use dioxus::desktop::tao::window::Icon;

pub const APP_ICON_BASE64: &str = "";

pub fn load_app_icon_raw() -> (Vec<u8>, u32, u32) {
    let bytes = BASE64_STANDARD.decode(APP_ICON_BASE64.as_bytes()).expect("valid app icon base64");
    let img = image::load_from_memory(&bytes).expect("valid png icon").to_rgba8();
    let (width, height) = img.dimensions();
    (img.into_raw(), width, height)
}

pub fn load_app_icon() -> Option<Icon> {
    let (raw, width, height) = load_app_icon_raw();
    Icon::from_rgba(raw, width, height).ok()
}

/// Returns a data URL (`data:image/png;base64,...`) for instant rendering in UI image tags.
pub fn app_icon_data_url() -> &'static str {
    static DATA_URL: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    DATA_URL.get_or_init(|| format!("data:image/png;base64,{}", APP_ICON_BASE64))
}


/// Embedded Attune Squircle App Tile Icon (Base64 Encoded PNG).
/// Used in the About stage hero banner and full-tile representations.
pub const APP_ICON_TILE_BASE64: &str = "";

#[allow(dead_code)]
pub fn load_app_tile_icon_raw() -> (Vec<u8>, u32, u32) {
    let bytes = BASE64_STANDARD.decode(APP_ICON_TILE_BASE64.as_bytes()).expect("valid tile icon base64");
    let img = image::load_from_memory(&bytes).expect("valid png tile icon").to_rgba8();
    let (width, height) = img.dimensions();
    (img.into_raw(), width, height)
}

#[allow(dead_code)]
pub fn load_app_tile_icon() -> Option<Icon> {
    let (raw, width, height) = load_app_tile_icon_raw();
    Icon::from_rgba(raw, width, height).ok()
}

/// Returns a data URL for the squircle app tile icon (`data:image/png;base64,...`).
pub fn app_icon_tile_data_url() -> &'static str {
    static TILE_DATA_URL: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    TILE_DATA_URL.get_or_init(|| format!("data:image/png;base64,{}", APP_ICON_TILE_BASE64))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_load_app_icon_dimensions_and_payload() {
        let (raw, width, height) = load_app_icon_raw();
        assert_eq!(width, 128);
        assert_eq!(height, 128);
        assert_eq!(raw.len(), 128 * 128 * 4);
        assert!(raw.iter().any(|&b| b > 0));
        let icon = load_app_icon();
        assert!(icon.is_some());
    }

    #[test]
    fn test_load_app_tile_icon_dimensions_and_payload() {
        let (raw, width, height) = load_app_tile_icon_raw();
        assert_eq!(width, 256);
        assert_eq!(height, 256);
        assert_eq!(raw.len(), 256 * 256 * 4);
        assert!(raw.iter().any(|&b| b > 0));
        let icon = load_app_tile_icon();
        assert!(icon.is_some());
    }

    #[test]
    fn test_app_icon_tile_data_url_prefix() {
        let url = app_icon_tile_data_url();
        assert!(url.starts_with("data:image/png;base64,"));
        assert!(url.len() > 100);
    }
}
